public function getStyle($cellCoordinate): Style
{
    $cellCoordinate = Validations::validateCellOrCellRange($cellCoordinate);
    [$worksheetName] = Worksheet::extractSheetTitle($cellCoordinate, true);
    $worksheetName = str_replace("''", "'", trim((string) $worksheetName, "'"));
    if ($worksheetName !== '' && strcasecmp($worksheetName, $this->getTitle()) !== 0) {
        throw new Exception('Invalid Worksheet ' . $worksheetName);
    }

    // set this sheet as active
    $this->getParentOrThrow()->setActiveSheetIndex($this->getParentOrThrow()->getIndex($this));

    // set cell coordinate as active
    $this->setSelectedCells($cellCoordinate);

    return $this->getParentOrThrow()->getCellXfSupervisor();
}

